#include <benchmark/benchmark.h>

#include <cstdint>

extern "C" {
#include "core/data_structures/int64_hash_map.h"
}

static void BM_Int64HashMapSet(benchmark::State& state) {
    int64_t num_elements = state.range(0);
    double max_load_factor = state.range(1) / 100.0;

    for (auto _ : state) {
        Int64HashMap map;
        Int64HashMapInit(&map, max_load_factor);

        for (int64_t i = 0; i < num_elements; ++i) {
            benchmark::DoNotOptimize(Int64HashMapSet(&map, i, i * 7));
        }

        Int64HashMapDestroy(&map);
    }

    state.SetItemsProcessed(state.iterations() * num_elements);
}

BENCHMARK(BM_Int64HashMapSet)
    ->ArgsProduct({benchmark::CreateRange(1, 4096, /*multi=*/2), {50}});

static void BM_Int64HashMapGetHit(benchmark::State& state) {
    int64_t num_elements = state.range(0);
    double max_load_factor = state.range(1) / 100.0;

    Int64HashMap map;
    Int64HashMapInit(&map, max_load_factor);
    for (int64_t i = 0; i < num_elements; ++i) {
        Int64HashMapSet(&map, i, i * 7);
    }

    for (auto _ : state) {
        for (int64_t i = 0; i < num_elements; ++i) {
            benchmark::DoNotOptimize(Int64HashMapGet(&map, i));
        }
    }

    state.SetItemsProcessed(state.iterations() * num_elements);
    Int64HashMapDestroy(&map);
}

BENCHMARK(BM_Int64HashMapGetHit)
    ->ArgsProduct({benchmark::CreateRange(1, 4096, /*multi=*/2), {50}});

static void BM_Int64HashMapGetMiss(benchmark::State& state) {
    int64_t num_elements = state.range(0);
    double max_load_factor = state.range(1) / 100.0;

    Int64HashMap map;
    Int64HashMapInit(&map, max_load_factor);
    for (int64_t i = 0; i < num_elements; ++i) {
        Int64HashMapSet(&map, i, i * 7);
    }

    for (auto _ : state) {
        // Query keys that were never inserted.
        for (int64_t i = num_elements; i < 2 * num_elements; ++i) {
            benchmark::DoNotOptimize(Int64HashMapGet(&map, i));
        }
    }

    state.SetItemsProcessed(state.iterations() * num_elements);
    Int64HashMapDestroy(&map);
}

BENCHMARK(BM_Int64HashMapGetMiss)
    ->ArgsProduct({benchmark::CreateRange(1, 4096, /*multi=*/2), {50}});

static void BM_Int64HashMapIterate(benchmark::State& state) {
    int64_t num_elements = state.range(0);
    double max_load_factor = state.range(1) / 100.0;

    Int64HashMap map;
    Int64HashMapInit(&map, max_load_factor);
    for (int64_t i = 0; i < num_elements; ++i) {
        Int64HashMapSet(&map, i, i * 7);
    }

    for (auto _ : state) {
        Int64HashMapIterator it = Int64HashMapBegin(&map);
        int64_t key, value;
        while (Int64HashMapIteratorNext(&it, &key, &value)) {
            benchmark::DoNotOptimize(key);
            benchmark::DoNotOptimize(value);
        }
    }

    state.SetItemsProcessed(state.iterations() * num_elements);
    Int64HashMapDestroy(&map);
}

BENCHMARK(BM_Int64HashMapIterate)
    ->ArgsProduct({benchmark::CreateRange(1, 4096, /*multi=*/2), {50}});
